/** width/height attributes for a local image, so the browser reserves its space before it loads. Unknown or remote sources return {}. */
export function imgDims(src: string | undefined): { width?: number; height?: number } {
  const size = src ? imageSizes[src] : undefined;
  return size ? { width: size[0], height: size[1] } : {};
}
